def caesar(text, schritt):
    ergebnis = ""
    for c in text.upper():
        if "A" <= c <= "Z":
            ergebnis += chr((ord(c) - ord("A") + schritt) % 26 + ord("A"))
        else:
            ergebnis += c
    return ergebnis

